import ca.uhn.fhir.context.FhirContext;
import ca.uhn.fhir.context.support.DefaultProfileValidationSupport;
import ca.uhn.fhir.validation.FhirValidator;
import ca.uhn.fhir.validation.ResultSeverityEnum;
import ca.uhn.fhir.validation.SingleValidationMessage;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.hl7.fhir.common.hapi.validation.support.CommonCodeSystemsTerminologyService;
import org.hl7.fhir.common.hapi.validation.support.InMemoryTerminologyServerValidationSupport;
import org.hl7.fhir.common.hapi.validation.support.ValidationSupportChain;
import org.hl7.fhir.common.hapi.validation.validator.FhirInstanceValidator;

/**
 * Valida contra FHIR R4 o que a fachada devolve DE VERDADE pela rede.
 *
 * <p>Diferente da suite, que valida o objeto montado em memoria, este programa
 * busca por HTTP, no servidor em execucao, e valida o JSON que chegou no fio.
 */
public class ValidadorAoVivo {

    private static final String BASE = "http://localhost:8080/fhir";

    public static void main(String[] args) throws Exception {
        var contexto = FhirContext.forR4();
        var validador = contexto.newValidator();
        validador.registerValidatorModule(new FhirInstanceValidator(new ValidationSupportChain(
                new DefaultProfileValidationSupport(contexto),
                new InMemoryTerminologyServerValidationSupport(contexto),
                new CommonCodeSystemsTerminologyService(contexto))));

        var http = HttpClient.newHttpClient();

        // Controle negativo primeiro: se o validador nao reprovar isto, todo o
        // resto e evidencia falsa.
        var invalido = validador.validateWithResult(
                "{\"resourceType\":\"Patient\",\"id\":\"x\",\"gender\":\"banana\"}");
        var errosDoInvalido = errosDe(invalido.getMessages());
        System.out.println("CONTROLE NEGATIVO (gender=banana): "
                + errosDoInvalido.size() + " issue(s) de severidade error -> "
                + (errosDoInvalido.isEmpty() ? "FALHOU: validador nao valida" : "OK, validador funciona"));
        if (errosDoInvalido.isEmpty()) {
            System.exit(1);
        }
        System.out.println();

        var alvos = new ArrayList<String>();
        alvos.add("/Patient/10011");                 // nome social
        alvos.add("/Patient/10023");                 // sem CPF e sem CNS
        alvos.add("/Patient/10044");                 // tp_sexo = 'I'
        alvos.add("/Patient/10074");                 // obito anterior ao nascimento
        alvos.add("/Patient?name=sergio");           // Bundle de busca
        alvos.add("/Patient?_lastUpdated=ge2025-08-01&_lastUpdated=le2025-08-31");
        alvos.add("/metadata");                      // CapabilityStatement

        int totalDeErros = 0;
        for (var alvo : alvos) {
            var resposta = http.send(
                    HttpRequest.newBuilder(URI.create(BASE + alvo))
                            .header("Accept", "application/fhir+json").GET().build(),
                    HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));

            var erros = errosDe(validador.validateWithResult(resposta.body()).getMessages());
            totalDeErros += erros.size();

            System.out.printf("HTTP %d  %-60s issues 'error': %d%n",
                    resposta.statusCode(), alvo, erros.size());
            for (var erro : erros) {
                System.out.println("        -> " + erro.getLocationString() + ": " + erro.getMessage());
            }
        }

        System.out.println();
        System.out.println(totalDeErros == 0
                ? "RESULTADO: nenhum issue de severidade 'error' em nenhum recurso retornado."
                : "RESULTADO: " + totalDeErros + " issue(s) de severidade 'error'.");
        System.exit(totalDeErros == 0 ? 0 : 1);
    }

    private static List<SingleValidationMessage> errosDe(List<SingleValidationMessage> mensagens) {
        return mensagens.stream()
                .filter(m -> m.getSeverity() == ResultSeverityEnum.ERROR
                        || m.getSeverity() == ResultSeverityEnum.FATAL)
                .toList();
    }
}

